function EXTRA(R,ICON){
 /* hook: after the neutral breaks, the heavily loaded phase dims and the lightly loaded ones get too much voltage */
 ICON.ctDim=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${CT_T(20,36,'busy phase: dim',{fs:24,fw:800,fill:BLU})}${CT_lamp(80,100,0)}${CT_lamp(170,100,0)}${CT_lamp(260,100,0)}${CT_T(340,112,'↓',{fs:44,fw:800,a:'middle',fill:BLU})}</g>`;
 ICON.ctBurn=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CT_box(0,0,380,160,{fill:'#FFFFFF',st:RED,sw:3,r:18})}${CT_T(20,36,'others: too high',{fs:24,fw:800,fill:RED})}${CT_lamp(90,100,1,RED)}<rect x="190" y="66" width="110" height="72" rx="8" fill="#343A40" stroke="${CT_INK}" stroke-width="3"/>${CT_poly([[214,60],[230,44],[222,36],[240,18]],CT_MUT,4)}${CT_poly([[262,60],[278,42],[268,34],[284,14]],CT_MUT,4)}${CT_T(340,112,'↑',{fs:44,fw:800,a:'middle',fill:RED})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.ctTri=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="330" rx="18" fill="#EDF2FF"/>${CT_tri(40,280,1840,1380,0.165,[BLU,GRN,PUR],{w:7})}<path d="M120 280 A80 80 0 0 0 104 232" fill="none" stroke="${ORG}" stroke-width="5"/>${CT_T(126,262,'φ',{fs:32,fw:800,fill:ORG})}${CT_T(192,322,'P (W)',{fs:30,fw:800,a:'middle',fill:BLU})}${CT_T(356,170,'Q',{fs:30,fw:800,fill:GRN})}${CT_T(356,204,'(var)',{fs:24,fw:800,fill:GRN})}${CT_T(176,132,'|S| (VA)',{fs:30,fw:800,a:'end',fill:PUR})}</g>`;
 ICON.ctSD=(x,y)=>{const N=[100,160],T=[[100,60],[13,210],[187,210]],D=[[320,60],[230,216],[410,216]];return `<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="330" rx="18" fill="#FFF4E6"/>${T.map(t=>CT_z(N[0],N[1],t[0],t[1],ORG,4,40,16)+CT_dot(t[0],t[1])).join('')}${CT_dot(N[0],N[1],ORG,7)}${CT_z(D[0][0],D[0][1],D[1][0],D[1][1],ORG,4,40,16)}${CT_z(D[1][0],D[1][1],D[2][0],D[2][1],ORG,4,40,16)}${CT_z(D[2][0],D[2][1],D[0][0],D[0][1],ORG,4,40,16)}${D.map(t=>CT_dot(t[0],t[1])).join('')}${CT_T(100,276,'star',{fs:28,fw:800,a:'middle'})}${CT_T(100,318,'√3 × V',{fs:30,fw:800,a:'middle',fill:ORG})}${CT_T(320,276,'delta',{fs:28,fw:800,a:'middle'})}${CT_T(320,318,'√3 × I',{fs:30,fw:800,a:'middle',fill:ORG})}</g>`};
 ICON.ctNeu=(x,y)=>{const p1=CT_ph(20,230,0,130,GRN,5),p2=CT_ph(p1[1],p1[2],120,130,GRN,5),p3=CT_ph(p2[1],p2[2],-120,130,GRN,5),n=[300,160],k=100/230.9,np=[300+57.7*k,160],tp=[[400,160],[250,246.6],[250,73.4]];
  return `<g transform="translate(${x-210} ${y-165})"><rect x="-14" y="10" width="448" height="330" rx="18" fill="#EBFBEE"/>${p1[0]+p2[0]+p3[0]}${CT_T(85,276,'balanced',{fs:26,fw:800,a:'middle'})}${CT_T(85,316,`${CT_sub('I','N')} = 0`,{fs:30,fw:800,a:'middle',fill:GRN})}${tp.map(t=>CT_L(np[0],np[1],t[0],t[1],ORG,4)+CT_dot(t[0],t[1])).join('')}${CT_dot(n[0],n[1],CT_MUT,6)}${CT_dot(np[0],np[1],TRED,8)}${CT_T(316,140,'N′',{fs:26,fw:800,fill:TRED})}${CT_T(320,276,'no neutral',{fs:26,fw:800,a:'middle'})}${CT_T(320,316,'N′ shifts',{fs:30,fw:800,a:'middle',fill:TRED})}</g>`};
}
